#[derive(sqlx::FromRow)]
pub struct Invoice { pub id: i64, pub amount: Decimal, pub due: NaiveDate }

pub struct PgInvoiceRepository { pool: PgPool }   // Send + Sync, cloneable handle

impl PgInvoiceRepository {
    pub async fn find_overdue(&self, on: NaiveDate) -> Result<Vec<Invoice>, sqlx::Error> {
        sqlx::query_as::<_, Invoice>("SELECT id, amount, due FROM invoice WHERE due < $1")
            .bind(on)                              // SQL never leaves this module
            .fetch_all(&self.pool)
            .await
    }
}

