pub struct DieselInvoiceRepository<C> { conn: C }        // C: Connection

impl<C: Connection<Backend = Pg>> DieselInvoiceRepository<C> {
    pub fn find_overdue(&mut self, on: NaiveDate) -> QueryResult<Vec<Invoice>> {
        use crate::schema::invoices::dsl::*;              // generated schema, no hand SQL
        invoices.filter(due.lt(on)).select(Invoice::as_select()).load(&mut self.conn)
    }
}
